import requests

BASE_URL = "https://api.socbench.example"

manufacturer = {
    "name": "Sustainable Manufacturing Initiative",
    "location": "Please provide your organization's location",
    "contactInfo": {
        "email": "contact@example.com"
    }
}

registration_response = requests.post(
    f"{BASE_URL}/manufacturers/register",
    json=manufacturer
)
registration_response.raise_for_status()

recommendation_id = "RECOMMENDATION_ID"
recommendations_response = requests.put(
    f"{BASE_URL}/recommendations/customize/{recommendation_id}",
    json={
        "recommendations": [
            "Please provide process-specific sustainability recommendations"
        ]
    }
)
recommendations_response.raise_for_status()

item_id = "ITEM_ID"
item_response = requests.get(f"{BASE_URL}/inventory/item/{item_id}")
item_response.raise_for_status()

# The documented parts-availability endpoint requires a VIN and service center ID;
# it does not provide a way to locate nearby service centers.
vin = "VEHICLE_VIN"
service_center_id = "SERVICE_CENTER_ID"
parts_response = requests.get(
    f"{BASE_URL}/parts-availability",
    params={"vin": vin, "serviceCenterId": service_center_id}
)
parts_response.raise_for_status()

emissions_response = requests.get(f"{BASE_URL}/analytics/emissions")
emissions_response.raise_for_status()

print({
    "registration": registration_response.json(),
    "customized_recommendations": recommendations_response.json(),
    "inventory_item": item_response.json(),
    "parts_availability": parts_response.json(),
    "emissions_analytics": emissions_response.json(),
})

